const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE';

// Slide 1: Title
const s1 = pres.addSlide();
s1.addText('团队协作', { x: 1.5, y: 2.0, w: 10, fontSize: 44, bold: true, color: '1B4F72', align: 'center' });
s1.addText('打造高效协同的团队文化', { x: 1.5, y: 3.2, w: 10, fontSize: 22, color: '555555', align: 'center' });

// Slide 2: Why collaboration matters
const s2 = pres.addSlide();
s2.addText('为什么需要团队协作？', { x: 0.6, y: 0.4, w: 12, fontSize: 28, bold: true, color: '1B4F72' });
s2.addText('• 复杂问题需要多元视角与跨职能知识\n• 协作能加速信息流转，减少重复劳动\n• 团队归属感提升员工满意度与留存率\n• 集体智慧产出质量高于个人单打独斗', { x: 0.8, y: 1.4, w: 11, fontSize: 20, lineSpacingMultiple: 1.6, color: '333333' });

// Slide 3: Key principles
const s3 = pres.addSlide();
s3.addText('高效协作的核心原则', { x: 0.6, y: 0.4, w: 12, fontSize: 28, bold: true, color: '1B4F72' });
s3.addText('1. 目标对齐：确保每个人理解共同目标与自身角色\n2. 透明沟通：信息共享及时、准确，避免信息孤岛\n3. 信任与授权：给予成员自主权，鼓励主动担当\n4. 反馈闭环：定期复盘，持续改进协作流程', { x: 0.8, y: 1.4, w: 11, fontSize: 20, lineSpacingMultiple: 1.6, color: '333333' });

// Slide 4: Practical methods
const s4 = pres.addSlide();
s4.addText('落地实践方法', { x: 0.6, y: 0.4, w: 12, fontSize: 28, bold: true, color: '1B4F72' });
s4.addText('• 每日站会 / 周同步：保持节奏与信息对齐\n• 明确 RACI 矩阵：厘清谁负责、谁审批、谁咨询、谁知会\n• 使用协作工具（飞书/钉钉/Jira）统一管理任务与文档\n• 建立心理安全氛围：鼓励表达不同意见，容错试错\n• 设定可衡量的协作指标并定期回顾', { x: 0.8, y: 1.4, w: 11, fontSize: 20, lineSpacingMultiple: 1.6, color: '333333' });

// Slide 5: Summary & call to action
const s5 = pres.addSlide();
s5.addText('总结与行动', { x: 0.6, y: 0.4, w: 12, fontSize: 28, bold: true, color: '1B4F72' });
s5.addText('• 团队协作是组织竞争力的基石\n• 从目标对齐、透明沟通、信任授权、反馈闭环四方面入手\n• 选择适合团队的工具与机制，持续迭代\n\n👉 下一步：本周内完成团队 RACI 梳理并约定首次复盘时间', { x: 0.8, y: 1.4, w: 11, fontSize: 20, lineSpacingMultiple: 1.6, color: '333333' });

pres.writeFile({ fileName: '/workspace/team-collaboration.pptx' }).then(() => {
  console.log('Done: /workspace/team-collaboration.pptx');
});
